def update_sqlite():
    if not os.path.exists(DB_PATH):
        print(f"❌ Database not found at {DB_PATH}")
        return

    conn = sqlite3.connect(DB_PATH)
    cur = conn.cursor()

    # 1. Update dav_national_drugs for all 20 medications
    print("🚀 Updating dav_national_drugs in SQLite...")
    updated_dav = 0
    for d in DRUG_AUDIT_DATA:
        sdk = d["national_code"]
        cur.execute("""
            UPDATE dav_national_drugs
            SET brand_name = ?,
                active_ingredient = ?,
                concentration = ?,
                dosage_form = ?,
                packaging_spec = ?,
                standard_pharmacopeia = ?,
                shelf_life = ?,
                route = ?,
                [group] = ?,
                manufacturer = ?,
                country = ?,
                applicant_name = ?,
                approval_decision = ?,
                atc_code = ?,
                drug_class = ?,
                is_controlled = ?,
                is_high_alert = ?,
                is_crash_cart = ?,
                hdsd_path = ?,
                label_path = ?,
                indications = ?,
                contraindications = ?,
                precautions = ?,
                pregnancy_warning = ?,
                adult_dosage = ?,
                pediatric_dosage = ?,
                renal_adjustment = ?,
                hepatic_adjustment = ?,
                adverse_effects = ?,
                drug_interactions = ?,
                overdose_treatment = ?,
                antidote = ?,
                clinical_source = ?,
                clinical_monograph_id = ?
            WHERE national_code = ? OR id = ? OR id = ?
        """, (
            d["brand_name"], d["active_ingredient"], d["concentration"], d["dosage_form"],
            d["packaging_spec"], d["standard_pharmacopeia"], d["shelf_life"], d["route"],
            d["group"], d["manufacturer"], d["country"], d["applicant_name"], d["approval_decision"],
            d["atc_code"], d["drug_class"], d["is_controlled"], d["is_high_alert"], d["is_crash_cart"],
            d["hdsd_path"], d["label_path"], d["indications"], d["contraindications"], d["precautions"],
            d["pregnancy_warning"], d["adult_dosage"], d["pediatric_dosage"], d["renal_adjustment"],
            d["hepatic_adjustment"], d["adverse_effects"], d["drug_interactions"], d["overdose_treatment"],
            d["antidote"], d["clinical_source"], d["clinical_monograph_id"],
            sdk, sdk, f"dav-{sdk}"
        ))
        if cur.rowcount > 0:
            updated_dav += 1
        else:
            print(f"⚠️ Could not find dav record for SDK {sdk}")

    # 2. Update clinical_drug_monographs for all 20 medications
    print("🚀 Updating clinical_drug_monographs in SQLite...")
    updated_mono = 0
    for d in DRUG_AUDIT_DATA:
        mono_id = d["clinical_monograph_id"]
        cur.execute("""
            INSERT INTO clinical_drug_monographs (
                id, inn, title, atc_code, drug_class, dosage_forms,
                indications, contraindications, precautions, pregnancy_warning,
                adverse_effects, adult_dosage, pediatric_dosage, renal_adjustment,
                hepatic_adjustment, drug_interactions, overdose_treatment, antidote, source
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(id) DO UPDATE SET
                inn = excluded.inn,
                title = excluded.title,
                atc_code = excluded.atc_code,
                drug_class = excluded.drug_class,
                dosage_forms = excluded.dosage_forms,
                indications = excluded.indications,
                contraindications = excluded.contraindications,
                precautions = excluded.precautions,
                pregnancy_warning = excluded.pregnancy_warning,
                adverse_effects = excluded.adverse_effects,
                adult_dosage = excluded.adult_dosage,
                pediatric_dosage = excluded.pediatric_dosage,
                renal_adjustment = excluded.renal_adjustment,
                hepatic_adjustment = excluded.hepatic_adjustment,
                drug_interactions = excluded.drug_interactions,
                overdose_treatment = excluded.overdose_treatment,
                antidote = excluded.antidote,
                source = excluded.source
        """, (
            mono_id, d["active_ingredient"], d["brand_name"], d["atc_code"], d["drug_class"], d["dosage_form"],
            d["indications"], d["contraindications"], d["precautions"], d["pregnancy_warning"],
            d["adverse_effects"], d["adult_dosage"], d["pediatric_dosage"], d["renal_adjustment"],
            d["hepatic_adjustment"], d["drug_interactions"], d["overdose_treatment"], d["antidote"], d["clinical_source"]
        ))
        updated_mono += 1

    # 3. Update inventory_batches to ensure 100% sync
    print("🚀 Updating inventory_batches in SQLite...")
    for d in DRUG_AUDIT_DATA:
        cur.execute("""
            UPDATE inventory_batches
            SET item_name = ?,
                registration_number = ?,
                national_code = ?,
                active_ingredient = ?,
                concentration = ?,
                dosage_form = ?,
                packaging_spec = ?,
                standard_pharmacopeia = ?,
                shelf_life = ?,
                manufacturer = ?,
                country = ?,
                applicant_name = ?,
                approval_decision = ?,
                route = ?
            WHERE id = ?
        """, (
            d["brand_name"], d["national_code"], d["national_code"], d["active_ingredient"],
            d["concentration"], d["dosage_form"], d["packaging_spec"], d["standard_pharmacopeia"],
            d["shelf_life"], d["manufacturer"], d["country"], d["applicant_name"],
            d["approval_decision"], d["route"], d["batch_id"]
        ))

    conn.commit()
    conn.close()
    print(f"✅ SQLite Update Complete: {updated_dav} DAV rows, {updated_mono} Monographs updated.")

def update_formulary_json():
    if not os.path.exists(JSON_PATH):
        print(f"❌ JSON not found at {JSON_PATH}")
        return

    with open(JSON_PATH, "r", encoding="utf-8") as f:
        items = json.load(f)

    # Index by nationalCode / registrationNumber / id
    sdk_to_idx = {}
    for idx, it in enumerate(items):
        for k in ["nationalCode", "registrationNumber", "id", "national_code"]:
            val = it.get(k)
            if val:
                sdk_to_idx[str(val).strip().lower()] = idx

    updated_count = 0
    for d in DRUG_AUDIT_DATA:
        sdk = d["national_code"].lower()
        json_obj = {
            "id": f"dav-{d['national_code']}",
            "nationalCode": d["national_code"],
            "registrationNumber": d["national_code"],
            "brandName": d["brand_name"],
            "activeIngredient": d["active_ingredient"],
            "concentration": d["concentration"],
            "dosageForm": d["dosage_form"],
            "packagingSpec": d["packaging_spec"],
            "standardPharmacopeia": d["standard_pharmacopeia"],
            "shelfLife": d["shelf_life"],
            "route": d["route"],
            "group": d["group"],
            "manufacturer": d["manufacturer"],
            "country": d["country"],
            "applicantName": d["applicant_name"],
            "approvalDecision": d["approval_decision"],
            "atcCode": d["atc_code"],
            "drugClass": d["drug_class"],
            "isControlled": bool(d["is_controlled"]),
            "isHighAlert": bool(d["is_high_alert"]),
            "isCrashCart": bool(d["is_crash_cart"]),
            "hdsdPath": d["hdsd_path"],
            "labelPath": d["label_path"],
            "indications": d["indications"],
            "contraindications": d["contraindications"],
            "precautions": d["precautions"],
            "pregnancyWarning": d["pregnancy_warning"],
            "adultDosage": d["adult_dosage"],
            "pediatricDosage": d["pediatric_dosage"],
            "renalAdjustment": d["renal_adjustment"],
            "hepaticAdjustment": d["hepatic_adjustment"],
            "adverseEffects": d["adverse_effects"],
            "drugInteractions": d["drug_interactions"],
            "overdoseTreatment": d["overdose_treatment"],
            "antidote": d["antidote"],
            "clinicalSource": d["clinical_source"],
            "clinical_source": d["clinical_source"],
            "clinicalMonographId": d["clinical_monograph_id"],
            "isVerified": True
        }

        if sdk in sdk_to_idx:
            idx = sdk_to_idx[sdk]
            items[idx].update(json_obj)
        else:
            items.append(json_obj)
            sdk_to_idx[sdk] = len(items) - 1
        updated_count += 1

    with open(JSON_PATH, "w", encoding="utf-8") as f:
        json.dump(items, f, ensure_ascii=False, indent=2)
    print(f"✅ JSON Update Complete: {updated_count} medications synchronized in dav_essential_formulary.json.")

if __name__ == "__main__":
    update_sqlite()
    update_formulary_json()
